import type { VocabularyItem } from './vocabularyService.ts';

/**
 * Authored starter vocabulary — common words every beginner course needs.
 * Every entry is hand-written with a real meaning and a real example sentence;
 * nothing here is generated or templated. The goal is depth of quality, not
 * padded counts: banks stay small until more real content is authored.
 */
function makeStarter(lang: string, index: number, word: string, pos: string, vi: string, en: string, ex: string, exVi: string, romanization?: string): VocabularyItem {
  return {
    id: `${lang}-starter-${String(index).padStart(3, '0')}`,
    language: lang,
    level: 'A1',
    word,
    nativeScript: word,
    romanization: romanization || word,
    partOfSpeech: pos,
    meaning: en,
    translation: vi,
    meaningEnglish: en,
    meaningVietnamese: vi,
    example: ex,
    exampleTranslation: exVi,
    tags: ['A1', 'Cơ bản'],
    topic: 'Cơ bản',
    difficulty: 1,
    mastery: 0,
  };
}

type StarterRow = [word: string, pos: string, vi: string, en: string, example: string, exampleVi: string, romanization?: string];

function buildStarter(lang: string, rows: StarterRow[], offset = 0): VocabularyItem[] {
  return rows.map((row, i) => makeStarter(lang, offset + i + 1, row[0], row[1], row[2], row[3], row[4], row[5], row[6]));
}

function makeStarterA2(lang: string, index: number, word: string, pos: string, vi: string, en: string, ex: string, exVi: string, romanization?: string): VocabularyItem {
  return {
    id: `${lang}-a2-${String(index).padStart(3, '0')}`,
    language: lang,
    level: 'A2',
    word,
    nativeScript: word,
    romanization: romanization || word,
    partOfSpeech: pos,
    meaning: en,
    translation: vi,
    meaningEnglish: en,
    meaningVietnamese: vi,
    example: ex,
    exampleTranslation: exVi,
    tags: ['A2', 'Sơ trung cấp'],
    topic: 'Sơ trung cấp',
    difficulty: 2,
    mastery: 0,
  };
}

function buildStarterA2(lang: string, rows: StarterRow[], offset = 0): VocabularyItem[] {
  return rows.map((row, i) => makeStarterA2(lang, offset + i + 1, row[0], row[1], row[2], row[3], row[4], row[5], row[6]));
}

